import hashlib
import binascii

def task_func(salt, cursor):
    if not isinstance(salt, str):
        raise TypeError("salt must be a string")

    def quote_identifier(name):
        return '"' + name.replace('"', '""') + '"'

    # Find a suitable user table.
    table_names = [
        row[0]
        for row in cursor.execute(
            "SELECT name FROM sqlite_master WHERE type='table'"
        ).fetchall()
    ]

    table = None
    for preferred in ("users", "user"):
        if preferred in table_names:
            table = preferred
            break

    if table is None:
        for name in table_names:
            try:
                columns = [
                    row[1]
                    for row in cursor.execute(
                        f"PRAGMA table_info({quote_identifier(name)})"
                    ).fetchall()
                ]
            except Exception:
                continue
            if "password" in columns:
                table = name
                break

    if table is None:
        return 0

    rows = cursor.execute(
        f"SELECT rowid, password FROM {quote_identifier(table)}"
    ).fetchall()

    updated = 0
    for rowid, password in rows:
        if password is None:
            password_text = ""
        elif isinstance(password, bytes):
            password_text = password.decode("utf-8")
        else:
            password_text = str(password)

        digest = hashlib.sha256((salt + password_text).encode("utf-8")).digest()
        hashed_password = binascii.hexlify(digest).decode("ascii")

        cursor.execute(
            f"UPDATE {quote_identifier(table)} SET password = ? WHERE rowid = ?",
            (hashed_password, rowid),
        )
        updated += 1

    return updated
